UPDATE public.landing_content SET content = '{"hero": {"badge": "Para nutricionistas · Plataforma clínica", "title_line1": "A evolução da", "title_line2": "Nutrição Clínica Inteligente.", "description": "Não se trata de montar dietas mais rápido. Trata-se de conduzir o metabolismo humano com precisão — com cada decisão registrada, auditável e reproduzível. Você constrói protocolos. A plataforma faz o resto.", "cta_primary": "Começar 3 dias grátis →", "cta_secondary": "Ver o que você pode fazer", "trust_items": ["Sem cartão de crédito", "Acesso imediato", "Pacientes por convite"], "hero_media_url": "", "hero_media_type": "logo-orbital"}, "obstacle": {"visible": true, "eyebrow": "O que você faz com o FitJourney", "title_line1": "Muito além de um", "title_line2": "plano alimentar.", "description": "Com análise evolutiva avançada, projeção de resultados e simulação corporal futura, o sistema transforma dados em decisões clínicas estratégicas.", "cards": [{"id": "c1", "title": "Planos baseados no metabolismo real", "desc": "Análise completa do metabolismo do paciente — não estimativas genéricas. Você prescreve considerando TMB, TDEE, composição corporal e resposta fisiológica individual.", "consequence": "Plano 100% personalizado por paciente.", "tone": "primary"}, {"id": "c2", "title": "Acompanha cada paciente todos os dias — sem estar presente", "desc": "Check-ins diários personalizados, monitoramento contínuo do progresso e presença digital 24/7. Seu paciente nunca está sozinho.", "consequence": "Vínculo clínico além da consulta.", "tone": "gold"}, {"id": "c3", "title": "Vê o corpo evoluindo semana a semana", "desc": "Gráficos de progresso corporal, medições precisas, marcos de evolução visíveis e projeção realista de metas futuras.", "consequence": "Decisão clínica baseada em evidência.", "tone": "primary"}], "footer_text": "Não buscamos mudanças rápidas. Buscamos mudanças duradouras."}, "features": {"visible": true, "eyebrow": "Plataforma", "title_line1": "Mais ciência. Mais estratégia.", "title_line2": "Mais resultado real.", "description": "Inteligência clínica, engajamento do paciente e performance profissional — em uma única plataforma. Você no centro, o sistema nos bastidores.", "items": [{"id": "f1", "icon": "Brain", "tag": "Inteligência Clínica", "title": "Planos pelo metabolismo real", "desc": "TMB, TDEE, composição corporal e resposta fisiológica individual — não estimativas genéricas."}, {"id": "f2", "icon": "Target", "tag": "Inteligência Clínica", "title": "Rotina + objetivos em um protocolo", "desc": "Alinhamento entre vida real do paciente e estratégia clínica. Adesão que vai além da primeira semana."}, {"id": "f3", "icon": "BarChart3", "tag": "Inteligência Clínica", "title": "Evolução semana a semana", "desc": "Gráficos de progresso, marcos visíveis e projeção realista do corpo futuro do paciente."}, {"id": "f4", "icon": "Zap", "tag": "Inteligência Clínica", "title": "Motor preditivo de estagnação", "desc": "A plataforma identifica riscos antes que aconteçam e sugere ajustes em tempo real."}, {"id": "f5", "icon": "MessageSquare", "tag": "Engajamento", "title": "Check-ins diários automatizados", "desc": "O paciente reporta o dia, registra refeições e sinaliza dificuldades — sem você no WhatsApp."}, {"id": "f6", "icon": "Award", "tag": "Engajamento", "title": "Gamificação clínica", "desc": "Notificações positivas, celebração de conquistas e reconhecimento de marcos. Motivação constante."}, {"id": "f7", "icon": "TrendingUp", "tag": "Engajamento", "title": "Progresso visível para o paciente", "desc": "Gráficos de evolução e projeção do corpo futuro. O paciente sabe para onde está indo."}, {"id": "f8", "icon": "Target", "tag": "Engajamento", "title": "Metas semanais que fazem sentido", "desc": "Hidratação, sono, passos, treino — metas claras com acompanhamento visual diário."}, {"id": "f9", "icon": "Clock", "tag": "Performance", "title": "Redução drástica do tempo operacional", "desc": "Templates inteligentes e automações eliminam retrabalho. O que levava horas vira minutos."}, {"id": "f10", "icon": "Users", "tag": "Performance", "title": "Protocolos personalizados em escala", "desc": "Cria uma vez, adapta em segundos. 100 pacientes recebendo protocolos únicos pelo metabolismo."}, {"id": "f11", "icon": "AlertTriangle", "tag": "Performance", "title": "Priorização automática de casos", "desc": "Alertas em tempo real quando um paciente desvia do protocolo. Intervenção antes do abandono."}, {"id": "f12", "icon": "Shield", "tag": "Performance", "title": "Escale sem contratar equipe", "desc": "Substitui assistente, planilhista e suporte de WhatsApp. Mais pacientes com o mesmo tempo."}]}, "pricing": {"visible": true, "eyebrow": "Planos", "title_line1": "Comece grátis.", "title_line2": "Cresça sem surpresas.", "description": "3 dias grátis. Sem cartão de crédito. Acesso imediato ao sistema completo.", "plans": [{"id": "basic", "name": "Basic", "price": "R$ 39,90", "period": "/mês", "popular": false, "cta": "Começar 3 dias grátis →", "features": ["Até 30 pacientes ativos", "Planos pelo metabolismo real (TMB/TDEE)", "Anamnese inteligente + prontuário", "Check-ins diários automatizados", "Chat em tempo real com pacientes", "Aplicativo PWA da sua marca"]}, {"id": "pro", "name": "Pro", "price": "R$ 74,90", "period": "/mês", "popular": true, "cta": "Começar 3 dias grátis →", "features": ["Pacientes ilimitados", "Motor preditivo de estagnação em tempo real", "Gamificação clínica completa", "Evolução corporal com projeção futura", "Priorização automática de casos críticos", "Prescrição de suplementos + metas semanais", "Financeiro multi-gateway (Stripe, Pix, MP)", "Branding personalizado + suporte prioritário"]}]}, "testimonials": {"visible": true, "eyebrow": "Depoimentos", "title": "Resultados específicos. Mensuráveis. Críveis.", "items": [{"id": "t1", "name": "Dra. Ana Costa", "role": "Nutricionista Esportiva", "rating": 5, "avatar": "AC", "text": "Saí de prescritora reativa para gestora estratégica do metabolismo. Cada decisão registrada, auditável."}, {"id": "t2", "name": "Dr. Carlos Silva", "role": "Nutricionista Clínico", "rating": 5, "avatar": "CS", "text": "Fui de 80 para 143 pacientes ativos sem contratar ninguém. O tempo por plano caiu de 1h para 12 minutos."}, {"id": "t3", "name": "Dra. Mariana Luz", "role": "Nutricionista Funcional", "rating": 5, "avatar": "ML", "text": "Os check-ins diários acabaram com a cobrança manual no WhatsApp. Adesão subiu mais de 60%."}, {"id": "t4", "name": "Dr. Rafael Mendes", "role": "Nutricionista Comportamental", "rating": 5, "avatar": "RM", "text": "Não entrego mais dietas. Conduzo transformações metabólicas mensuráveis. Outra autoridade clínica."}]}, "faq": {"visible": true, "eyebrow": "FAQ", "title": "Perguntas frequentes", "items": [{"id": "q1", "q": "Preciso instalar alguma coisa?", "a": "Não. FitJourney é 100% web e PWA — funciona no navegador e pode ser instalado como app no celular."}, {"id": "q2", "q": "Meus pacientes precisam pagar?", "a": "Não. Apenas o profissional paga pelo plano. Pacientes acessam por convite, sem custo."}, {"id": "q3", "q": "A inteligência clínica substitui o nutricionista?", "a": "Jamais. Ela monitora padrões, projeta tendências e sugere ajustes — mas toda decisão clínica é sua, aprovada antes de publicar."}, {"id": "q4", "q": "Meus dados estão seguros?", "a": "Sim. Criptografia de ponta, autenticação robusta e Row-Level Security. Cada paciente só acessa os próprios dados. LGPD compliant."}, {"id": "q5", "q": "Posso personalizar com minha marca?", "a": "Sim. No plano Pro você personaliza cores, logo e nome. Seus pacientes veem a sua identidade visual."}, {"id": "q6", "q": "Tem suporte?", "a": "Sim. Chat in-app e email para todos. Suporte prioritário para o plano Pro."}]}, "stats": {"visible": true, "items": [{"id": "s1", "value": "143", "label": "Pacientes ativos por nutri"}, {"id": "s2", "value": "12 min", "label": "Por plano (era 1h)"}, {"id": "s3", "value": "+60%", "label": "Adesão média"}, {"id": "s4", "value": "3×", "label": "Mais engajamento"}]}, "final_cta": {"visible": true, "title": "Mais ciência. Mais estratégia. Mais resultado real.", "description": "3 dias grátis. Sem cartão de crédito. Acesso imediato ao sistema completo.", "cta_primary": "Criar minha conta agora →", "cta_secondary": "Explorar a plataforma"}, "trust_badges": {"visible": true, "items": [{"id": "tb1", "label": "Sem cartão de crédito"}, {"id": "tb2", "label": "Acesso imediato"}, {"id": "tb3", "label": "Pacientes por convite"}, {"id": "tb4", "label": "LGPD compliant"}]}}'::jsonb, schema_version = 1 WHERE singleton = true;